"uajewa": "Una <b>prueba de mercado</b> es una inversión pequeña para aprender antes de apostar fuerte. Define antes qué medirás y qué resultado te haría continuar.",
"r2g9va": "Con <b>muestras pequeñas</b> el azar pesa mucho: 3 ventas contra 1 no demuestra que un mercado sea el triple de bueno. Hace falta un volumen mínimo de datos o repetir la prueba.",
"1ylmuyx": "Compara mercados con el mismo indicador y el mismo periodo.",
"1b7ordi": "Francia: 12 ventas con 1.000 €. Bélgica: 4 ventas con 300 €. El CPA es parecido (83 € frente a 75 €); no hay datos suficientes para decir que Bélgica es mejor.",
"zjytyh": "Declarar un ganador después de dos días.",
