"mh8cwl": "Usar la inteligencia artificial con calidad, transparencia y respeto.",
"151t4ma": "La IA puede acelerar tareas: borradores de textos, variaciones de anuncios, resúmenes de informes, clasificación de datos. Pero puede cometer errores, inventar datos o reproducir sesgos.",
"f65orf": "Principios: <b>supervisión humana</b> de todo lo que se publica, <b>no introducir datos personales</b> de clientes en herramientas sin garantías, <b>transparencia</b> cuando el contenido lo requiera y respeto de los <b>derechos de autor</b> y de la imagen de las personas.",
"bazieo": "La IA no sustituye la estrategia ni el conocimiento del cliente: es una herramienta para dedicar más tiempo a pensar.",
"1ftst3d": "La agencia usa IA para generar 20 variantes de titulares, pero una persona las revisa, elige 4 y comprueba que no hacen promesas falsas antes de probarlas.",
