"syqlzh": "{agencia} sigue siendo independiente, rentable y arraigada al territorio. Tiene una cartera estable, clientes fieles y un equipo pequeño que quiere su trabajo.",
"11nyvik": "{nom} ha priorizado la calidad, las relaciones y la sostenibilidad. Cuando alguien de Osona pregunta «¿quién me puede ayudar con el marketing?», la respuesta suele ser la misma.",
"1pxzzte": "Final 2 — Referentes en una especialidad",
"sg59dr": "{agencia} se ha convertido en un referente técnico. Recibe proyectos complejos, trabaja con clientes grandes y es conocida por la calidad de sus resultados.",
"o3zyyx": "Las universidades invitan a {nom} a dar clases y los competidores estudian sus casos.",
"1vwvrv0": "Final 3 — El grupo internacional",
"1gxhre": "{agencia} ha crecido en varios mercados. {nom} dirige equipos en Vic, Barcelona y Lyon, y unidades de negocio que nunca habría imaginado.",
"i3mxj8": "Ha aprendido a equilibrar crecimiento, rentabilidad y complejidad. Algunos días echa de menos aquel despacho encima de la mercería.",
"1lzmfjj": "Final 4 — Volver a poner orden",
"vu1hl5": "La empresa creció demasiado deprisa y acumuló problemas de tesorería y gestión. Ha sido necesario reducir la estructura y renegociar deudas.",
"1tso70t": "No es una derrota: {agencia} es ahora más pequeña, pero ordenada. {nom} ha aprendido la lección más cara de todas: crecer no es lo mismo que mejorar.",
"qnefqe": "Final 5 — La vida que querías",
"l001oh": "{nom} ha decidido no perseguir el crecimiento indefinido. Ha construido una empresa viable que le permite elegir proyectos, cuidar al equipo y tener tiempo para vivir.",
"wa4628": "Los sábados sigue comprando el pan en la panadería de Carme. Y sigue haciendo preguntas antes de proponer nada.",
"18jps4f": "La venta se cierra a un precio excelente: la reputación de la agencia valía mucho. El equipo conserva el trabajo y la marca.",
"j5e461": "La venta se cierra, pero a un precio modesto. El equipo continúa bajo otra dirección.",
"o9ejtw": "Carme ha abierto un obrador y vende cocas a veinte cafeterías de la comarca.",
"1xr4fe7": "Mecanitzats Bellmunt exporta a cinco países. Miquel todavía dice que «los me gusta no pagan nóminas».",
"xq6g3y": "Júlia es socia de la agencia y da clases de analítica en la universidad.",
"gsf9zz": "Berta ha ganado un premio de creatividad con una campaña que, además, vendió.",
"130xvxd": "Laia y {nom} comparten proyectos cada año. La competencia se ha convertido en alianza.",
"1wgi1f9": "Sergi acabó descubriendo que aquella primera campaña no había vendido nada. Nunca lo olvidó.",
