"1jfol1v": "Ver resultados",
"v4zg8p": "Los alumnos que escriben un código de clase en el juego envían los resultados automáticamente cada vez que terminan un capítulo. También puedes añadir archivos de resultados que te hayan enviado (botón de abajo).",
