"erp7u": "Mira en la Biblioteca de anuncios de Meta qué hacen hornos y cafeterías reales antes de diseñar.",
"1vox0tk": "Un anuncio con demasiado texto no se lee: una idea, una imagen, una acción.",
"1bmvitk": "Estrategia de SEO local y reseñas para Can Jordi",
