"1bothas": "6. Corrección y revisión",
"17k4sbq": "En pocos minutos, una corrección automática con IA lee el documento, lo puntúa con la rúbrica y te da comentarios. El profesor puede revisarla y cambiarla en cualquier momento. Si hay que mejorarlo, corrige el documento y vuelve a entregarlo. Mientras tanto puedes hacer encargos, lecciones y el Taller web.",
"16v4evn": "Cada proyecto se evalúa con la rúbrica de su guía: cada criterio tiene 4 niveles (de 0 a 3 puntos) y la nota es la proporción de puntos obtenidos sobre 10. Se aprueba con un 5. La corrección automática solo puede leer documentos públicos de Google (Docs, Slides, Sheets), PDF, imágenes y páginas web: si usas Canva o vídeo, entrega también un PDF. La nota final la decide siempre el profesor.",
