"ssv33r": "Peluquería Marisa",
"16guw4c": "¡Pierdo citas! Me piden hora por WhatsApp mientras corto y me olvido de contestar.",
"o58xbn": "Reserva en línea con recordatorios automáticos, enlazada desde Instagram y Google",
"1dyjopt": "Las citas se reservan solas y ya no se olvida ninguna. Marisa te paga 160 €.",
"1eak3vp": "Contratar a una recepcionista solo para el WhatsApp",
"1wa0dlx": "Demasiado coste para un negocio pequeño. Le habías recomendado una empresa de selección y tienes que pagar 250 € de la comisión.",
"e39xtx": "Contestar los mensajes por la noche",
"nq7zis": "Funciona, pero Marisa acaba agotada. Te paga 30 €.",
"158rlgg": "Capítulo {0}: {1}",
