"owyi8x": "Llega al nivel {0} para continuar: ayuda a los comerciantes de Vic o haz encargos.",
"1hle35a": "Yo voy al horno de Carme cada mañana, desde hace cuarenta años. ¿Por la tarde? Por la tarde pasaban las familias del colegio, pero ya no.",
"16lbocs": "Quería pan para merendar, pero Google dice que el horno de Carme cierra a las dos. Qué pena, tendré que ir al súper.",
"1gauz76": "Aquí estaba mi juguetería. Treinta y dos años. Cuando llegaron las compras en línea, no quise cambiar nada...",
"v6mno1": "Si volviera a empezar, escucharía más lo que querían los clientes. Tú que haces marketing, no dejes que les pase a los demás.",
"1rv59qi": "¡Gracias por el cupón de la merienda! Los niños ya lo piden cada martes.",
"cl4yw4": "Ahora el colegio sale a las cuatro y media y vamos directos al parque. Antes pasábamos por el horno.",
"1tetk9": "¿Sabes que en el súper venden cruasanes a 30 céntimos? Son de plástico, ¡pero son baratos!",
"1qo8pxs": "Cojo el tren hacia Barcelona. Los informes, el lunes a primera hora, ¿de acuerdo?",
"18ev6c1": "Abrimos hasta las nueve de la noche, cada día. Por la tarde viene mucha gente a buscar pan de barra.",
"z9bs8g": "El pan de aquí no es como el del horno, pero a las siete de la tarde es el único sitio abierto.",
"5wm3f3": "La coca de chicharrones de Carme es la mejor de Vic. Pero eso, en internet, no lo dice en ninguna parte.",
"17m44qi": "Bocadillo en la nave cada día. ¿Can Jordi? Sí que está bien, pero no sabía que hicieran menú entre semana.",
"1r8zzcw": "Soy de los pocos que vienen un lunes. Trabajo en el polígono y lo descubrí por casualidad.",
"272ped": "¡He intentado comprar fuets por internet con el móvil y el botón de pagar no hace nada! He tenido que venir a la tienda.",
"g6jw6j": "Bienvenida a la feria, competencia. Aquí se ganan los clientes que no salen en Google.",
"108gbp": "¡Ya he programado las publicaciones de la semana! ¿Qué más puedo hacer?",
"2fjs9j": "Tengo tres reuniones esta semana con empresas del polígono. Las propuestas, en el ordenador.",
"z1bzcx": "Hacemos piezas para máquinas agrícolas de media Europa. Pero la web... la hizo el sobrino del gerente en 2011.",
"1y2smto": "▶ Empezar la misión",
"1fv8d4y": "¡Pasa, pasa! Hoy la coca de vidre ha salido buenísima.",
"1x0jewo": "Lunes, comedor medio vacío... Si sabes cómo llenarlo, te invito a comer.",
"r7k160": "¡El fuet de Vic de toda la vida! Ahora también lo enviamos a toda Cataluña.",
"p7oh5u": "Mira qué chaqueta nueva. Ya tengo la foto para Instagram... ¿o mejor miramos primero las ventas?",
"lb1u6r": "Aquí no se habla de seguidores. Se habla de piezas, plazos y compradores.",
"3p5k7e": "¡Hola!",
"1utkxo3": "¿Qué quieres hacer?",
"5vm5vc": "Nada, gracias",
