"n609ao": "La libreta de pedidos en línea. Todas las compras de este mes vienen de ordenador.",
"1wjbc8r": "La caja de la charcutería. Todavía hay más tiques de papel que de tarjeta.",
"1xz9e7i": "El ordenador de la tienda tiene abierto el panel de la web.",
"1rf5lm4": "El ordenador de la tienda, con el Excel de proveedores abierto.",
