"188pupe": "Una abogada avisa de que algunas webs de los clientes no cumplen la normativa.",
"fpwgws": "Soy Elena, abogada de la cámara de comercio. He revisado tres webs que lleváis: cookies sin opción de rechazar, formularios sin información de privacidad y ningún aviso legal.",
