"1plbz8x": "Seguir a todo el mundo en Instagram y esperar",
"1duyw40": "Cim Trail vende desde Instagram",
"1wus2sf": "Sergi quiere vender directamente en las redes y tener un perfil de empresa completo.",
"lc76n3": "Ahora que miramos las ventas y no los seguidores, quiero que Instagram y LinkedIn vendan de verdad. Quién sabe, quizá incluso TikTok.",
"1j4jp1r": "¿Cómo preparas las páginas?",
"1d3qfdv": "Usar el perfil personal de Sergi",
"1fvcefl": "Gestionó la marca desde un perfil personal sin herramientas profesionales.",
"jybk67": "Solo cambiar la foto de perfil",
"1a0smzq": "¿Cómo vendéis en las redes?",
"5sphvi": "Vender por mensaje privado sin condiciones ni facturas",
"rekd97": "Ventas sin factura ni condiciones: problemas fiscales y devoluciones (−400 €).",
"12yranq": "Poner el enlace de la web en la bio y ya está",
"140t53f": "Los clientes como prescriptores",
"1wt186o": "Jordi quiere que las opiniones de los clientes trabajen a su favor.",
"1585idh": "Después de la crisis, los clientes nos vuelven a querer. ¿Cómo hacemos que lo expliquen ellos, y no nosotros?",
"13cleg5": "Comprar 200 reseñas de cinco estrellas",
"auq572": "Google eliminó las reseñas falsas y penalizó la ficha; el cliente reclamó (−800 €).",
"1wn3lc7": "Responder solo las opiniones buenas",
"e0enwc": "Un comparador de restaurantes propone una oferta cruzada con una bodega. ¿Cómo lo valoras?",
"1ezxhus": "Bien, si el público es el mismo y se mide con un código propio: los consumidores proactivos comparan y aprovechan ofertas cruzadas",
"irqjdx": "Mal: los comparadores siempre perjudican",
"14ijafd": "Aceptarla sin medir nada",
"n8v5gc": "Dónde mira el usuario y dónde se pierde el dinero",
"t7qow3": "Núria vende más que nunca, pero la caja no cuadra y la web no convierte.",
"fnj846": "Las ventas suben, pero la cuenta del banco no. Y en la web, mucha gente pone fuets en el carrito y se va.",
"12tkom3": "¿Qué analizas y cambias en la web?",
"7mkot3": "Mapas de calor para ver las zonas calientes, el envío refrigerado arriba, compra como invitado y área de cliente para repetir pedidos",
"1569oqa": "Añadir más animaciones en la página de inicio",
"1igrj61": "Hacer el logo más grande con Photoshop",
"r130ef": "¿Por qué no cuadra la caja?",
"zl8rxu": "Porque paga stock y publicidad antes de que la pasarela ingrese los cobros, y no cuenta comisiones ni devoluciones: hace falta un plan de flujo de caja semanal",
"utxo0o": "Porque vende demasiado",
"sewwhg": "Porque hay que subir todos los precios un 30 %",
"m8qua7": "La subida de precios hizo caer las ventas y Núria redujo la cuota (−300 €).",
"4vd3wz": "Osona TV se reinventa",
"1hy3288": "La televisión local pierde audiencia en la TDT y quiere crecer en internet.",
"lwd85d": "La gente joven no mira la TDT. Tenemos programas buenos, pero nadie los encuentra. Y los anunciantes locales ya no nos llaman.",
"a72k3": "Subir los programas enteros a YouTube sin editar",
"19e4ajd": "Cerrar la TDT y hacer solo TikTok",
"192jen6": "La televisión perdió a los anunciantes de siempre (−500 €).",
"1mljssn": "Temario",
"1plk3f3": "📚 El temario",
"pqvrkr": "Puntos trabajados: <b>{0}</b> de {1}. Cada lección, misión, proyecto, web y acción del mundo trabaja unos puntos del temario.",
"yjpvlx": "Buena",
"zsjl9o": "Mala",
